  const [resolutionTimes, setResolutionTimes] = useState([]);
  const [topLocations, setTopLocations] = useState([]);
  const [openTickets, setOpenTickets] = useState([]);
  const [closedTickets, setClosedTickets] = useState([]);
  const baseApiPath = role === "admin" ? "api/admin/" : "api/";

  useEffect(() => {
    fetchLocationsAndDepartments();
    if (tabValue === 1) fetchTickets();
    if (tabValue === 2) {
      fetchWeeklySummary();
      fetchUrgentTickets();
      fetchResolutionTimes();
      fetchTopLocations();
      fetchOpenClosedTickets();
    }
  }, [tabValue, page, rowsPerPage]);

  const fetchLocationsAndDepartments = async () => {
    try {
      const locationsResponse = await axios.get(
        "https://support.mcdonalds.mu/api/location/list",
        {
          headers: { Authorization: `Bearer ${token}` },
        },
      );
      const departmentsResponse = await axios.get(
        "https://support.mcdonalds.mu/api/department/list",
        {
          headers: { Authorization: `Bearer ${token}` },
        },
      );
      setLocations(locationsResponse.data.data || []);
      setDepartments(departmentsResponse.data.data || []);
    } catch (error) {
      console.error("Error fetching locations and departments:", error);
      setLocations([]);
      setDepartments([]);
    }
  };

